    int by = blockIdx.y;

    // Each thread computes COARSE_FACTOR x COARSE_FACTOR elements
    float sum[COARSE_FACTOR][COARSE_FACTOR];

    // Initialize accumulation registers
    #pragma unroll
    for (int i = 0; i < COARSE_FACTOR; ++i) {
        #pragma unroll
        for (int j = 0; j < COARSE_FACTOR; ++j) {
            sum[i][j] = 0.0f;
